15	} from './store';
16	import type { Database, RunStatus, Stage, StageContext, StageName } from './types';
17	
18	const defaultSleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
19	
20	const STAGE_ORDER: StageName[] = ['ingest', 'edit', 'verify', 'script', 'ground', 'voice', 'render', 'review', 'gate'];
21	
22	function ensureRecutFeedbackTable(db: Database): void {
23	  db.exec('CREATE TABLE IF NOT EXISTS recut_feedback (run_id TEXT PRIMARY KEY, feedback TEXT NOT NULL)');
24	}
25	
26	function readRecutFeedback(db: Database, runId: string): string | null {
27	  ensureRecutFeedbackTable(db);
28	  const row = db.prepare('SELECT feedback FROM recut_feedback WHERE run_id = ?').get(runId) as
29	    | { feedback: string }
30	    | undefined;
31	  return row?.feedback ?? null;
32	}
33	
34	export function recut(db: Database, runId: string, feedback: string): void {
35	  if (!isStageDone(db, runId, 'verify')) {
36	    throw new Error(`cannot recut run ${runId}: the verify stage never completed`);
37	  }
38	  ensureRecutFeedbackTable(db);
39	  const scriptIndex = STAGE_ORDER.indexOf('script');
40	  db.transaction(() => {
41	    for (let i = scriptIndex; i < STAGE_ORDER.length; i++) resetStage(db, runId, STAGE_ORDER[i]!);
42	    db.prepare(
43	      `INSERT INTO recut_feedback (run_id, feedback) VALUES (?, ?)
44	       ON CONFLICT(run_id) DO UPDATE SET feedback = excluded.feedback`,
45	    ).run(runId, feedback);
46	    setRunFinal(db, runId, 'running', null);
47	  })();
48	}
49	
50	export async function runPipeline(
51	  db: Database,
